// ========== Parse v5 - kill CoT / word-counting dumps ==========
const body = $('Webhook').first().json.body || {};
const rawText = String($('Basic LLM Chain').first().json.text || '');

const name = body.name || 'Creator';
const email = body.email || '';
const idea = body.idea || '';
const duration = body.duration || '';
const language = body.language || 'Arabic';
const contentType = body.contentType || 'other';

function cleanRaw(text) {
  let t = text;
  // Kill common CoT / planning blocks
  const kill = [
    /Here's a thinking process:[\s\S]*/gi,
    /thinking process:[\s\S]*/gi,
    /Analyze the Request:[\s\S]*/gi,
    /Let me think[\s\S]*/gi,
    /Step[- ]by[- ]step[\s\S]*/gi,
    /My reasoning:[\s\S]*/gi,
    /<think>[\s\S]*?<\/think>/gi,
    /\[thinking\][\s\S]*?\[\/thinking\]/gi,
    /```thinking[\s\S]*?```/gi,
    /```json\s*/gi,
    /```\s*/g,
    /Make sure total words[\s\S]*/gi,
    /Let's draft[\s\S]*/gi,
    /We'll write roughly[\s\S]*/gi,
    /We need to count words[\s\S]*/gi,
    /I'll write and then approximate[\s\S]*/gi,
    /Now we need to output JSON[\s\S]*/gi,
    /Now total words[\s\S]*/gi,
    /Great, \d+ words[\s\S]*/gi,
    /approx 750[\s\S]*/gi,
    /We must escape newlines[\s\S]*/gi,
    /We'll construct script string[\s\S]*/gi,
  ];
  for (const re of kill) t = t.replace(re, '');
  return t.trim();
}

function unescapeString(s) {
  if (typeof s !== 'string') return '';
  return s
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\r')
    .replace(/\\t/g, '\t')
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, '\\');
}

function tryParseJson(text) {
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first === -1 || last === -1 || last <= first) return null;
  let candidate = text.slice(first, last + 1);
  candidate = candidate.replace(/,\s*([}\]])/g, '$1');
  try { return JSON.parse(candidate); } catch (e) { return null; }
}

function extractField(text, fieldName) {
  const re = new RegExp('"' + fieldName + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"', 's');
  const m = text.match(re);
  if (m) return unescapeString(m[1]);
  return null;
}

function isMetaLine(line) {
  const t = line.trim();
  if (!t) return false;
  // Word counting / drafting patterns
  if (/^(Hook|Intro|Section|Outro)\s*text\s*:/i.test(t)) return true;
  if (/^(That's about|So \d+ words|Count words|Let's count|Now count|Aim ~|Add maybe|Now total|Great,)/i.test(t)) return true;
  if (/^\d+\s+words\.?$/i.test(t)) return true;
  if (/^(First|Second|Third|Finally),?\s+\w+\s+words/i.test(t)) return true;
  if (/word(s)?\s*[:=]\s*\d+/i.test(t)) return true;
  if (/^(Make sure total|Let's draft|We'll write|We need to|I'll write|Now we need)/i.test(t)) return true;
  if (/^(HOOK|INTRO|SECTION|OUTRO)\s*$/i.test(t) === false && /^\[.*\]$/.test(t)) return true; // [content] placeholders
  if (/^\[Hook spoken|^\[Intro\]|^\[content\]|^\[closing\]/i.test(t)) return true;
  return false;
}

function stripMetaAndEnglishLeak(script, lang) {
  if (!script) return script;
  let lines = script.split('\n');
  // Drop pure meta lines
  lines = lines.filter(line => !isMetaLine(line));
  // If Arabic, drop mostly-Latin lines (except headers)
  if (lang === 'Arabic') {
    lines = lines.filter(line => {
      const t = line.trim();
      if (!t || t.startsWith('##')) return true;
      const ar = (t.match(/[\u0600-\u06FF]/g) || []).length;
      const en = (t.match(/[a-zA-Z]/g) || []).length;
      if (en > 20 && ar < 5) return false;
      return true;
    });
  }
  let s = lines.join('\n');
  // Hard cut from known tails
  const cutAt = [
    /\n\s*Make sure total words[\s\S]*$/i,
    /\n\s*Let's draft[\s\S]*$/i,
    /\n\s*We'll write roughly[\s\S]*$/i,
    /\n\s*We need to count[\s\S]*$/i,
    /\n\s*Now total words[\s\S]*$/i,
    /\n\s*Now we need to output[\s\S]*$/i,
    /\n\s*We must escape[\s\S]*$/i,
    /\n\s*"script"\s*:\s*"[\s\S]*$/i,
  ];
  for (const re of cutAt) s = s.replace(re, '');
  return s.replace(/\n{3,}/g, '\n\n').trim();
}

function extractScriptFromText(text) {
  const markers = [
    /^##\s*HOOK\b/im,
    /^##\s*INTRO\b/im,
    /^##\s*الافتتاحية/m,
    /^##\s*المقدمة/m,
    /^##\s*SECTION\s*1/im,
    /^##\s*الجزء الأول/m,
    /^##\s+/m,
  ];
  for (const re of markers) {
    const m = text.search(re);
    if (m !== -1) return text.slice(m).trim();
  }
  return null;
}

let script = '';
let youtube = { titles: [], description: '', tags: [] };
let hooks = [];

const cleaned = cleanRaw(rawText);
const parsed = tryParseJson(cleaned);

if (parsed && typeof parsed === 'object') {
  script = unescapeString(String(parsed.script || '').trim());
  if (parsed.youtube && typeof parsed.youtube === 'object') {
    youtube = {
      titles: Array.isArray(parsed.youtube.titles) ? parsed.youtube.titles.filter(Boolean) : [],
      description: typeof parsed.youtube.description === 'string' ? parsed.youtube.description : '',
      tags: Array.isArray(parsed.youtube.tags) ? parsed.youtube.tags.filter(Boolean) : [],
    };
  }
  hooks = Array.isArray(parsed.hooks) ? parsed.hooks.filter(Boolean) : [];
}

if (!script || script.length < 80) {
  const manual = extractField(cleaned, 'script');
  if (manual && manual.length > 80) script = manual;
}

if (!script || script.length < 80) {
  const extracted = extractScriptFromText(cleaned);
  if (extracted && extracted.length > 80) script = extracted;
}

// Aggressive meta strip
script = stripMetaAndEnglishLeak(script, language);
script = script
  .replace(/^[\s\{\}]*"script"\s*:\s*"/i, '')
  .replace(/"\s*,\s*"youtube"[\s\S]*$/i, '')
  .replace(/\\n/g, '\n')
  .trim();
script = stripMetaAndEnglishLeak(script, language);

if (!script || script.length < 50) {
  script = language === 'Arabic'
    ? 'تعذر توليد السكريبت بشكل صحيح. جرب مرة تانية أو غيّر الموديل.'
    : 'Failed to generate the script correctly. Please try again or switch the model.';
}

return [{
  json: {
    script,
    youtube,
    hooks,
    name,
    email,
    idea,
    duration,
    language,
    contentType,
  }
}];

// ========== Format HTML Email ==========
const d = $('Parse Script').first().json;
const script = d.script || '';
const name = d.name || 'Creator';
const email = d.email || '';
const duration = d.duration || '';
const language = d.language || 'Arabic';
const youtube = d.youtube || {};
const hooks = d.hooks || [];

function esc(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

let html = esc(script)
  .replace(/^### (.+)$/gm, '<h3 style="color:#f6c453;margin:22px 0 10px;font-size:17px;font-weight:700;">$1</h3>')
  .replace(/^## (.+)$/gm, '<h2 style="color:#ff5b3a;margin:26px 0 12px;font-size:19px;font-weight:700;border-bottom:1px solid rgba(255,91,58,0.25);padding-bottom:6px;">$1</h2>')
  .replace(/^# (.+)$/gm, '<h1 style="color:#ff7a5c;margin:28px 0 14px;font-size:21px;font-weight:800;">$1</h1>')
  .replace(/\*\*(.+?)\*\*/g, '<strong style="color:#f6c453;font-weight:700;">$1</strong>')
  .replace(/\*(.+?)\*/g, '<em style="color:#9a9288;">$1</em>')
  .replace(/\[([^\]]+)\]/g, '<span style="display:inline-block;background:rgba(255,91,58,0.12);color:#ff7a5c;padding:2px 8px;border-radius:4px;font-size:12px;font-weight:600;border:1px solid rgba(255,91,58,0.25);margin:2px 0;">[$1]</span>')
  .replace(/\n\n/g, '</p><p style="margin:14px 0;line-height:1.85;">')
  .replace(/\n/g, '<br/>');

const titles = (youtube.titles || []).map(t =>
  `<li style="padding:8px 12px;background:#141210;border:1px solid rgba(255,240,220,0.09);border-radius:6px;margin-bottom:6px;font-size:14px;font-weight:600;color:#f4efe8;">${esc(t)}</li>`
).join('');

const hooksHtml = (hooks || []).map(h =>
  `<li style="padding:8px 12px;background:#141210;border:1px solid rgba(255,240,220,0.09);border-radius:6px;margin-bottom:6px;font-size:14px;font-weight:600;color:#f4efe8;">${esc(h)}</li>`
).join('');

const tagsHtml = (youtube.tags || []).map(tg =>
  `<span style="display:inline-block;background:rgba(255,91,58,0.12);color:#ff5b3a;border:1px solid rgba(255,91,58,0.3);padding:4px 10px;border-radius:999px;font-size:11px;font-weight:600;margin:3px;">${esc(tg)}</span>`
).join('');

const metaBlock = (titles || youtube.description || tagsHtml || hooksHtml) ? `
  <tr><td style="padding:8px 36px 0;">
    <div style="background:rgba(255,240,220,0.03);border:1px solid rgba(255,240,220,0.09);border-radius:12px;padding:20px;">
      ${titles ? `<div style="font-family:'Courier New',monospace;font-size:11px;font-weight:700;letter-spacing:1px;color:#9a9288;text-transform:uppercase;margin-bottom:10px;">TITLES</div><ul style="list-style:none;padding:0;margin:0 0 20px;">${titles}</ul>` : ''}
      ${hooksHtml ? `<div style="font-family:'Courier New',monospace;font-size:11px;font-weight:700;letter-spacing:1px;color:#9a9288;text-transform:uppercase;margin-bottom:10px;">HOOKS</div><ul style="list-style:none;padding:0;margin:0 0 20px;">${hooksHtml}</ul>` : ''}
      ${youtube.description ? `<div style="font-family:'Courier New',monospace;font-size:11px;font-weight:700;letter-spacing:1px;color:#9a9288;text-transform:uppercase;margin-bottom:10px;">DESCRIPTION</div><div style="font-size:13px;line-height:1.7;color:#9a9288;white-space:pre-wrap;margin-bottom:20px;">${esc(youtube.description)}</div>` : ''}
      ${tagsHtml ? `<div style="font-family:'Courier New',monospace;font-size:11px;font-weight:700;letter-spacing:1px;color:#9a9288;text-transform:uppercase;margin-bottom:10px;">TAGS</div><div>${tagsHtml}</div>` : ''}
    </div>
  </td></tr>` : '';

const emailHtml = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#0f0e0d;font-family:'IBM Plex Sans Arabic','Segoe UI',Tahoma,Arial,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#0f0e0d;padding:40px 16px;">
    <tr><td align="center">
      <table width="640" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;background:#191715;border:1px solid rgba(255,240,220,0.09);border-radius:16px;overflow:hidden;">
        <tr><td style="padding:28px 36px;border-bottom:1px solid rgba(255,240,220,0.06);">
          <div style="font-size:20px;font-weight:800;color:#f4efe8;letter-spacing:-0.5px;">🎬 ScriptAI</div>
          <div style="font-size:13px;color:#9a9288;margin-top:4px;">سكريبتك جاهز</div>
        </td></tr>
        <tr><td style="padding:28px 36px 8px;">
          <p style="color:#f4efe8;font-size:16px;margin:0 0 8px;">أهلاً <strong style="color:#ff5b3a;">${esc(name)}</strong>،</p>
          <p style="color:#9a9288;font-size:14px;line-height:1.7;margin:0 0 20px;">ده السكريبت الاحترافي بتاعك. يارب الفيديو يعمل نجاح كبير! 🚀</p>
          <div style="margin-bottom:24px;">
            <span style="display:inline-block;background:rgba(255,91,58,0.12);color:#ff5b3a;padding:6px 14px;border-radius:999px;font-size:12px;font-weight:600;border:1px solid rgba(255,91,58,0.3);">⏱️ ${esc(duration)} دقيقة</span>
            <span style="display:inline-block;background:rgba(246,196,83,0.12);color:#f6c453;padding:6px 14px;border-radius:999px;font-size:12px;font-weight:600;border:1px solid rgba(246,196,83,0.3);margin-inline-start:6px;">🌐 ${esc(language)}</span>
          </div>
        </td></tr>${metaBlock}
        <tr><td style="padding:24px 36px 8px;">
          <div style="font-family:'Courier New',monospace;font-size:11px;font-weight:700;letter-spacing:1px;color:#9a9288;text-transform:uppercase;margin-bottom:10px;">SCRIPT</div>
          <div style="background:rgba(255,240,220,0.03);border:1px solid rgba(255,240,220,0.06);border-radius:12px;padding:24px 26px;color:#d8dae5;font-size:15px;line-height:1.85;direction:${language === 'Arabic' ? 'rtl' : 'ltr'};">
            <p style="margin:14px 0;line-height:1.85;">${html}</p>
          </div>
        </td></tr>
        <tr><td style="padding:24px 36px 32px;border-top:1px solid rgba(255,240,220,0.06);text-align:center;">
          <p style="color:#625c54;font-size:12px;margin:0;">© ${new Date().getFullYear()} ScriptAI</p>
        </td></tr>
      </table>
    </td></tr>
  </table>
</body></html>`;

return [{ json: { html: emailHtml, name, email, script: d.script, youtube: d.youtube, hooks: d.hooks, duration: d.duration, language: d.language, contentType: d.contentType } }];
